476	BOSNode *bostree_node_weak_ref(BOSNode *node) {
477		assert(node->weak_ref_count < 127);
478		assert(node->weak_ref_count > 0);
479		node->weak_ref_count++;
480		return node;
481	}
482	
483	BOSNode *bostree_node_weak_unref(BOSTree *tree, BOSNode *node) {
484		node->weak_ref_count--;
485		if(node->weak_ref_count == 0) {
486			if(tree->free_function) {
487				tree->free_function(node);
488			}
489			free(node);
490		}
491		else if(node->weak_ref_node_valid) {
492			return node;
493		}
494		return NULL;
495	}
496	
497	BOSNode *bostree_lookup(BOSTree *tree, const void *key) {
498		BOSNode *node = tree->root_node;
499		while(node) {
500			int cmp = tree->cmp_function(key, node->key);
501			if(cmp == 0) {
502				break;
503			}
504			else if(cmp < 0) {
505				node = node->left_child_node;
506			}
507			else {
508				node = node->right_child_node;
509			}
510		}
511		return node;
512	}
513	
514	BOSNode *bostree_select(BOSTree *tree, unsigned int index) {
515		BOSNode *node = tree->root_node;
516		while(node) {
517			if(node->left_child_count <= index) {
518				index -= node->left_child_count;
519				if(index == 0) {
520					return node;
521				}
522				index--;
523				node = node->right_child_node;
524			}
525			else {
526				node = node->left_child_node;
527			}
528		}
529		return node;
530	}
531	
532	BOSNode *bostree_next_node(BOSNode *node) {
533		if(node->right_child_node) {
534			node = node->right_child_node;
535			while(node->left_child_node) {
536				node = node->left_child_node;
537			}
538			return node;
539		}
540		else if(node->parent_node) {
541			while(node->parent_node && node->parent_node->right_child_node == node) {
542				node = node->parent_node;
543			}
544			return node->parent_node;
545		}
546		return NULL;
547	}
548	
549	BOSNode *bostree_previous_node(BOSNode *node) {
550		if(node->left_child_node) {
551			node = node->left_child_node;
552			while(node->right_child_node) {
553				node = node->right_child_node;
554			}
555			return node;
556		}
557		else if(node->parent_node) {
558			while(node->parent_node && node->parent_node->left_child_node == node) {
559				node = node->parent_node;
560			}
561			return node->parent_node;
562		}
563		return NULL;
564	}
565	
566	unsigned int bostree_rank(BOSNode *node) {
567		unsigned int counter = node->left_child_count;
568		while(node) {
569			if(node->parent_node && node->parent_node->right_child_node == node) counter += 1 + node->parent_node->left_child_count;
570			node = node->parent_node;
571		}
572		return counter;
573	}
