    let l_rc = p_rc.borrow().left_child_node.clone().unwrap();

    // Step 2: Get P's parent info
    let p_parent_weak = p_rc.borrow().parent_node.clone();
    let p_is_left_child = p_parent_weak.as_ref().and_then(|w| w.upgrade()).map(|parent| {
        let p_ref = parent.borrow();
        p_ref.left_child_node.as_ref().map_or(false, |l| Rc::ptr_eq(l, &p_rc))
    });

    // Step 3: Get L's right child info
    let l_right = l_rc.borrow().right_child_node.clone();
    let l_right_count = l_rc.borrow().right_child_count;

    // Step 4: Update parent pointer or tree root
    if let Some(parent_rc) = p_parent_weak.as_ref().and_then(|w| w.upgrade()) {
        if p_is_left_child.unwrap() {
            parent_rc.borrow_mut().left_child_node = Some(l_rc.clone());
        } else {
            parent_rc.borrow_mut().right_child_node = Some(l_rc.clone());
        }
