```rust
use std::cell::RefCell;
use std::rc::{Rc, Weak};

#[derive(Debug)]
pub struct BOSTree {
    pub root_node: Option<Rc<RefCell<BOSNode>>>,
    pub cmp_function: BOSTreeCmpFunction,
    pub free_function: Option<BOSTreeFreeFunction>,
}

#[derive(Debug)]
pub struct BOSNode {
    pub left_child_count: u32,
    pub right_child_count: u32,
    pub depth: u32,
    pub left_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub right_child_node: Option<Rc<RefCell<BOSNode>>>,
    pub parent_node: Option<Weak<RefCell<BOSNode>>>,
    pub key: String,
    pub data: Option<String>,
    pub weak_ref_count: u8,
    pub weak_ref_node_valid: u8,
}

pub type BOSTreeCmpFunction = fn(&str, &str) -> i32;
pub type BOSTreeFreeFunction = fn(&Rc<RefCell<BOSNode>>);

fn imax(a: u32, b: u32) -> u32 {
    std::cmp::max(a, b)
}

fn node_balance(node: &Rc<RefCell<BOSNode>>) -> i32 {
    let n = node.borrow();
    let left_depth: u32 = n.left_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
    let right_depth: u32 = n.right_child_node.as_ref().map_or(0, |c| c.borrow().depth + 1);
    right_depth as i32 - left_depth as i32
}

fn rotate_right(tree: &mut BOSTree, p_rc: Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let l_rc = p_rc.borrow().left_child_node.clone().unwrap();

    let p_parent_weak = p_rc.borrow().parent_node.clone();
    let p_is_left_child = p_parent_weak.as_ref().and_then(|w| w.upgrade()).map(|parent| {
        parent.borrow().left_child_node.as_ref().map_or(false, |l| Rc::ptr_eq(l, &p_rc))
    });

    let l_right = l_rc.borrow().right_child_node.clone();
    let l_right_count = l_rc.borrow().right_child_count;

    // Update parent or root
    match p_parent_weak.as_ref().and_then(|w| w.upgrade()) {
        Some(parent_rc) => {
            if p_is_left_child.unwrap() {
                parent_rc.borrow_mut().left_child_node = Some(l_rc.clone());
            } else {
                parent_rc.borrow_mut().right_child_node = Some(l_rc.clone());
            }
        }
        None => {
            tree.root_node = Some(l_rc.clone());
        }
    }

    // L.parent = P.parent
    l_rc.borrow_mut().parent_node = p_parent_weak;

    // P.left = L.right, P.left_count = L.right_count
    {
        let mut p_borrow = p_rc.borrow_mut();
        p_borrow.left_child_node = l_right;
        p_borrow.left_child_count = l_right_count;
    }

    // If P.left exists, set its parent to P
    if let Some(ref p_left) = p_rc.borrow().left_child_node {
        p_left.borrow_mut().parent_node = Some(Rc::downgrade(&p_rc));
    }

    // Update P.depth
    let p_left_depth = p_rc.borrow().left_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    let p_right_depth = p_rc.borrow().right_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    p_rc.borrow_mut().depth = imax(p_left_depth, p_right_depth);

    // P.parent = L
    p_rc.borrow_mut().parent_node = Some(Rc::downgrade(&l_rc));

    // L.right = P
    l_rc.borrow_mut().right_child_node = Some(p_rc.clone());

    // L.right_count = P.left_count + P.right_count + 1
    let p_lc = p_rc.borrow().left_child_count;
    let p_rc_count = p_rc.borrow().right_child_count;
    l_rc.borrow_mut().right_child_count = p_lc + p_rc_count + 1;

    // Update L.depth
    let l_left_depth = l_rc.borrow().left_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    let l_right_depth = l_rc.borrow().right_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    l_rc.borrow_mut().depth = imax(l_left_depth, l_right_depth);

    l_rc
}

fn rotate_left(tree: &mut BOSTree, p_rc: Rc<RefCell<BOSNode>>) -> Rc<RefCell<BOSNode>> {
    let r_rc = p_rc.borrow().right_child_node.clone().unwrap();

    let p_parent_weak = p_rc.borrow().parent_node.clone();
    let p_is_left_child = p_parent_weak.as_ref().and_then(|w| w.upgrade()).map(|parent| {
        parent.borrow().left_child_node.as_ref().map_or(false, |l| Rc::ptr_eq(l, &p_rc))
    });

    let r_left = r_rc.borrow().left_child_node.clone();
    let r_left_count = r_rc.borrow().left_child_count;

    // Update parent or root
    match p_parent_weak.as_ref().and_then(|w| w.upgrade()) {
        Some(parent_rc) => {
            if p_is_left_child.unwrap() {
                parent_rc.borrow_mut().left_child_node = Some(r_rc.clone());
            } else {
                parent_rc.borrow_mut().right_child_node = Some(r_rc.clone());
            }
        }
        None => {
            tree.root_node = Some(r_rc.clone());
        }
    }

    // R.parent = P.parent
    r_rc.borrow_mut().parent_node = p_parent_weak;

    // P.right = R.left, P.right_count = R.left_count
    {
        let mut p_borrow = p_rc.borrow_mut();
        p_borrow.right_child_node = r_left;
        p_borrow.right_child_count = r_left_count;
    }

    // If P.right exists, set its parent to P
    if let Some(ref p_right) = p_rc.borrow().right_child_node {
        p_right.borrow_mut().parent_node = Some(Rc::downgrade(&p_rc));
    }

    // Update P.depth
    let p_left_depth = p_rc.borrow().left_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    let p_right_depth = p_rc.borrow().right_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    p_rc.borrow_mut().depth = imax(p_left_depth, p_right_depth);

    // P.parent = R
    p_rc.borrow_mut().parent_node = Some(Rc::downgrade(&r_rc));

    // R.left = P
    r_rc.borrow_mut().left_child_node = Some(p_rc.clone());

    // R.left_count = P.left_count + P.right_count + 1
    let p_lc = p_rc.borrow().left_child_count;
    let p_rc_count = p_rc.borrow().right_child_count;
    r_rc.borrow_mut().left_child_count = p_lc + p_rc_count + 1;

    // Update R.depth
    let r_left_depth = r_rc.borrow().left_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    let r_right_depth = r_rc.borrow().right_child_node.as_ref().map_or(0u32, |n| n.borrow().depth + 1);
    r_rc.borrow_mut().depth = imax(r_left_depth, r_right_depth);

    r_rc
}

impl BOSTree {
    pub fn bostree_new(
        cmp_function: BOSTreeCmpFunction,
        free_function: Option<BOSTreeFreeFunction>,
    ) -> Self {
        BOSTree {
            root_node: None,
            cmp_function,
            free_function,
        }
    }

    pub fn bostree_node_count(&self) -> u32 {
        self.root_node.as_ref().map_or(0, |root| {
            let r = root.borrow();
            r.left_child_count + r.right_child_count + 1
        })
    }

    pub fn bostree_insert(&mut self, key: String, data: Option<String>) -> Rc<RefCell<BOSNode>> {
        let cmp_fn = self.cmp_function;

        // Find position and update child counts
        let mut current = self.root_node.clone();
        let mut parent_weak: Option<Weak<RefCell<BOSNode>>> = None;

        while let Some(node_rc) = current {
            parent_weak = Some(Rc::downgrade(&node_rc));
            let cmp = cmp_fn(&key, &node_rc.borrow().key);
            if cmp < 0 {
                node_rc.borrow_mut().left_child_count += 1;
                current = node_rc.borrow().left_child_node.clone();
            } else {
                node_rc.borrow_mut().right_child_count += 1;
                current = node_rc.borrow().right_child_node.clone();
            }
        }

        // Create new node
        let new_node = Rc::new(RefCell::new(BOSNode {
            left_child_count: 0,
            right_child_count: 0,
            depth: 0,
            left_child_node: None,
            right_child_node: None,
            parent_node: parent_weak.clone(),
            key,
            data,
            weak_ref_count: 1,
            weak_ref_node_valid: 1,
        }));

        // Link to parent
        match parent_weak {
            Some(ref pw) => {
                if let Some(parent_rc) = pw.upgrade() {
                    let cmp = cmp_fn(&new_node.borrow().key, &parent_rc.borrow().key);
                    if cmp < 0 {
                        parent_rc.borrow_mut().left_child_node = Some(new_node.clone());
                    } else {
                        parent_rc.borrow_mut().right_child_node = Some(new_node.clone());
                    }

                    // Check if depth changed (first child of parent)
                    let has_left = parent_rc.borrow().left_child_node.is_some();
                    let has_right = parent_rc.borrow().right_child_node.is_some();

                    if (has_left as u8) ^ (has_right as u8) == 1 {
                        // First child, depth changed
                        parent_rc.borrow_mut().depth += 1;

                        let mut bubble_node = parent_rc;

                        loop {
                            let parent_of_bubble_weak = bubble_node.borrow().parent_node.clone();
                            match parent_of_bubble_weak.as_ref().and_then(|w| w.upgrade()) {
                                Some(parent_of_bubble) => {
                                    let new_left_depth = parent_of_bubble.borrow().left_child_node.as_ref()
                                        .map_or(0u32, |n| n.borrow().depth + 1);
                                    let new_right_depth = parent_of_bubble.borrow().right_child_node.as_ref()
                                        .map_or(0u32, |n| n.borrow().depth + 1);
                                    let max_depth = imax(new_left_depth, new_right_depth);

                                    if parent_of_bubble.borrow().depth == max_depth {
                                        break;
                                    }
                                    parent_of_bubble.borrow_mut().depth = max_depth;

                                    if new_left_depth as i32 - 2 == new_right_depth as i32 {
                                        let left_child = parent_of_bubble.borrow().left_child_node.clone().unwrap();
                                        if node_balance(&left_child) > 0 {
                                            rotate_left(self, left_child);
                                        }
                                        bubble_node = rotate_right(self, parent_of_bubble);
                                    } else if new_left_depth as i32 + 2 == new_right_depth as i32 {
                                        let right_child = parent_of_bubble.borrow().right_child_node.clone().unwrap();
                                        if node_balance(&right_child) < 0 {
                                            rotate_right(self, right_child);
                                        }
                                        bubble_node = rotate_left(self, parent_of_bubble);
                                    } else {
                                        bubble_node = parent_of_bubble;
                                    }
                                }
                                None => break,
                            }
                        }
                    }
                }
            }
            None => {
                self.root_node = Some(new_node.clone());
            }
        }

        new_node
    }

    pub fn bostree_remove(&mut self, node: &Rc<RefCell<BOSNode>>) {
